/**
 * Hand-maintained mirror of `supabase/migrations/0001_init.sql`.
 *
 * Regenerate with:
 *   npx supabase gen types typescript --project-id <ref> > lib/supabase/types.ts
 */

export type TeamRow = {
  id: string;
  team_code: string;
  name: string;
  name_key: string;
  /** CTFd team password, generated by `register_team`. */
  ctfd_password: string;
  /** Set once the team exists on CTFd; null means not yet pushed. */
  ctfd_team_id: number | null;
  ctfd_synced_at: string | null;
  agreed_to_rules: boolean;
  created_at: string;
};

export type TeamMemberRow = {
  id: string;
  team_id: string;
  position: number;
  alias: string;
  first_name: string;
  last_name: string;
  student_id: string;
  email: string;
  /** `"<Team Name> | <Alias>"`, generated by `register_team`. */
  ctfd_username: string;
  /** CTFd member password, generated by `register_team`. */
  ctfd_password: string;
  /** Set once the user exists on CTFd; null means not yet pushed. */
  ctfd_user_id: number | null;
  ctfd_synced_at: string | null;
  created_at: string;
};

export type TeamInsert = Omit<TeamRow, "id" | "created_at">;
export type TeamMemberInsert = Omit<TeamMemberRow, "id" | "created_at">;

/** Payload for one member inside the `register_team` RPC. */
export type RegisterTeamMember = {
  alias: string;
  firstName: string;
  lastName: string;
  studentId: string;
  email: string;
};

export type Database = {
  public: {
    Tables: {
      teams: {
        Row: TeamRow;
        Insert: TeamInsert;
        Update: Partial<TeamInsert>;
        Relationships: [];
      };
      team_members: {
        Row: TeamMemberRow;
        Insert: TeamMemberInsert;
        Update: Partial<TeamMemberInsert>;
        Relationships: [];
      };
    };
    Views: Record<never, never>;
    Functions: {
      register_team: {
        Args: {
          p_team_name: string;
          p_team_code: string;
          p_members: RegisterTeamMember[];
        };
        Returns: TeamRow;
      };
    };
    Enums: Record<never, never>;
    CompositeTypes: Record<never, never>;
  };
};
